module max_minions_attack (\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] n,\n    input [3:0] m,\n    input [15:0] R,\n    input [15:0] village_x_0, village_y_0, village_r_0,\n    input [15:0] village_x_1, village_y_1, village_r_1,\n    input [15:0] minion_x_0, minion_y_0,\n    input [15:0] minion_x_1, minion_y_1,\n    input [15:0] minion_x_2, minion_y_2,\n    input [15:0] minion_x_3, minion_y_3,\n    input [15:0] minion_x_4, minion_y_4,\n    input [15:0] minion_x_5, minion_y_5,\n    input [15:0] minion_x_6, minion_y_6,\n    input [15:0] minion_x_7, minion_y_7,\n    output reg [7:0] max_count,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE             = 3'd0;\n    localparam [2:0] CHECK_VILLAGE    = 3'd1;\n    localparam [2:0] CHECK_VILLAGE_DONE = 3'd2;\n    localparam [2:0] COUNT_MINIONS    = 3'd3;\n    localparam [2:0] UPDATE_MAX       = 3'd4;\n    localparam [2:0] NEXT_CANDIDATE   = 3'd5;\n    localparam [2:0] DONE_STATE       = 3'd6;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [2:0] next_state;\n    reg [3:0] cand_idx;\n    reg [1:0] village_idx;\n    reg valid_candidate;\n    reg [7:0] current_count;\n    reg [31:0] R_sq;\n    reg [31:0] vr_plus_R_sq;\n    reg [31:0] dist_sq;\n    reg [15:0] dx;\n    reg [15:0] dy;\n    reg [15:0] minion_x [0:7];\n    reg [15:0] minion_y [0:7];\n    reg [15:0] village_x [0:1];\n    reg [15:0] village_y [0:1];\n    reg [15:0] village_r [0:1];\n\n    // Combinational minion count\n    integer k;\n    always @(*) begin\n        current_count = 8'd0;\n        if (valid_candidate) begin\n            for (k = 0; k < 8; k = k + 1) begin\n                if (k < m) begin\n                    reg [15:0] cand_x = minion_x[cand_idx];\n                    reg [15:0] cand_y = minion_y[cand_idx];\n                    reg [15:0] min_x = minion_x[k];\n                    reg [15:0] min_y = minion_y[k];\n                    reg [15:0] dx_temp;\n                    reg [15:0] dy_temp;\n                    reg [31:0] dist_sq_temp;\n\n                    dx_temp = (cand_x > min_x) ? cand_x - min_x : min_x - cand_x;\n                    dy_temp = (cand_y > min_y) ? cand_y - min_y : min_y - cand_y;\n                    dist_sq_temp = dx_temp * dx_temp + dy_temp * dy_temp;\n\n                    if (dist_sq_temp <= R_sq) begin\n                        current_count = current_count + 8'd1;\n                    end\n                end\n            end\n        end\n    end\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            max_count <= 8'd0;\n            done <= 1'b0;\n            cand_idx <= 4'd0;\n            village_idx <= 2'd0;\n            valid_candidate <= 1'b0;\n            R_sq <= 32'd0;\n            vr_plus_R_sq <= 32'd0;\n            dist_sq <= 32'd0;\n            dx <= 16'd0;\n            dy <= 16'd0;\n            // Load village data\n            village_x[0] <= village_x_0;\n            village_y[0] <= village_y_0;\n            village_r[0] <= village_r_0;\n            village_x[1] <= village_x_1;\n            village_y[1] <= village_y_1;\n            village_r[1] <= village_r_1;\n            // Load minion data\n            minion_x[0] <= minion_x_0; minion_y[0] <= minion_y_0;\n            minion_x[1] <= minion_x_1; minion_y[1] <= minion_y_1;\n            minion_x[2] <= minion_x_2; minion_y[2] <= minion_y_2;\n            minion_x[3] <= minion_x_3; minion_y[3] <= minion_y_3;\n            minion_x[4] <= minion_x_4; minion_y[4] <= minion_y_4;\n            minion_x[5] <= minion_x_5; minion_y[5] <= minion_y_5;\n            minion_x[6] <= minion_x_6; minion_y[6] <= minion_y_6;\n            minion_x[7] <= minion_x_7; minion_y[7] <= minion_y_7;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    max_count <= 8'd0;\n                    if (start) begin\n                        cand_idx <= 4'd0;\n                        village_idx <= 2'd0;\n                        valid_candidate <= 1'b1;\n                        R_sq <= R * R;\n                        state <= CHECK_VILLAGE;\n                    end\n                end\n\n                CHECK_VILLAGE: begin\n                    // Compute dx/dy between minion[cand_idx] and village[village_idx]\n                    dx <= (minion_x[cand_idx] > village_x[village_idx]) ? (minion_x[cand_idx] - village_x[village_idx]) : (village_x[village_idx] - minion_x[cand_idx]);\n                    dy <= (minion_y[cand_idx] > village_y[village_idx]) ? (minion_y[cand_idx] - village_y[village_idx]) : (village_y[village_idx] - minion_y[cand_idx]);\n                    vr_plus_R_sq <= (village_r[village_idx] + R) * (village_r[village_idx] + R);\n                    state <= CHECK_VILLAGE_DONE;\n                end\n\n                CHECK_VILLAGE_DONE: begin\n                    dist_sq <= dx * dx + dy * dy;\n                    if (dist_sq < vr_plus_R_sq) begin\n                        valid_candidate <= 1'b0;  // Invalid if inside any village\n                    end\n\n                    if (village_idx < n - 2'd1) begin\n                        village_idx <= village_idx + 2'd1;\n                        state <= CHECK_VILLAGE;\n                    end else begin\n                        state <= COUNT_MINIONS;\n                    end\n                end\n\n                COUNT_MINIONS: begin\n                    if (valid_candidate) begin\n                        state <= UPDATE_MAX;\n                    end else begin\n                        state <= NEXT_CANDIDATE;\n                    end\n                end\n\n                UPDATE_MAX: begin\n                    if (current_count > max_count) begin\n                        max_count <= current_count;\n                    end\n                    state <= NEXT_CANDIDATE;\n                end\n\n                NEXT_CANDIDATE: begin\n                    valid_candidate <= 1'b1;\n                    village_idx <= 2'd0;\n                    if (cand_idx < m - 4'd1) begin\n                        cand_idx <= cand_idx + 4'd1;\n                        state <= CHECK_VILLAGE;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule